        // >>> member: WrapWithQuotes
                public static String WrapWithQuotes(string s)
                {
                    // Shell Check
                    switch (VM.ConfigureView.Shell_SelectedItem)
                    {
                        // CMD
                        case "CMD":
                            // "my string"
                            return "\"" + s + "\"";
        
                        // PowerShell
                        case "PowerShell":
                            // Process Priority
                            switch (VM.ConfigureView.ProcessPriority_SelectedItem)
                            {
                                // Default
                                case "Default":
                                    // "my string"
                                    return "\"" + s + "\"";
        
                                // All Other Options (escape)
                                default:
                                    // `"my string`"
                                    return "`\"" + s + "`\"";
                            }
        
                        // Unknown
                        default:
                            return s;
                    }
                }

