                        string fps = @"(\d+.?\d+?\s?fps)";
        
                        // Subtitles
                        string langs = @"(Eng(lish)?|E|Ara(bic)?|Ben(gali)?|Chi(nese)?|Chn|Dut(ch)?|Fin(nish)?|Fre(nch)?|Ger(man)?|De|Hin(di)?|Ita(lian)?|Jap(anese)?|Kor(ean)?|Man(darin)?|Por(tuguese)?|Rus(sian)?|Spa(nish)?|Swe(dish)?|Tel(ugu)?|Vie(tnamese)?)";
                        string subs = @"(Subtitle(s|d)?|Sub(s)?)";
                        IEnumerable<string> subtitlesList = new List<string>()
                        {
                            langs + @"[\-\s]?" + subs,
                            subs + @"[\-\s]?" + langs,
                            langs.Replace("|E", "") // Fix words like Ben, Chi, Man
                                 .Replace("Ben(gali)?", "Bengali")
                                 .Replace("Chi(nese)?", "Chinese")
                                 .Replace("Man(darin)?", "Mandarin"),
                            @"(Multi[\-\s]?Sub(s)?|Subtitle(s|d)?|Sub(s|bed)?)"
                        };
                        string subtitles = string.Join("|", subtitlesList);
        
                        // Channel
                        IEnumerable<string> channelList = new List<string>()
                        {
                            @"(\d+(?:\.\d+)?[.\-_\s]?)?(CH)\s?(?(1)|([.\s]?\d+(?:\.\d+)?)?)",
                            @"(\d+(?:\.\d+)?[.-_\s]?)?((Dolby[.\-_\s]?(Digital)?)[.\-_\s]?(?:Pro[.\-_\s]?(Logic)?[.\-_\s]?(II)?|Surround|Atmos|TrueHD|Vision)?)[.\-_\s]?(?(1)|([.\s]?\d+(?:\.\d+)?)?)",
                            @"(\d+(?:\.\d+)?[.\-_\s]?)?(AC3|AAC|DTS|(DD(?:P|\+?)))(?(1)|([.\-_\s]?\d+(?:\.\d+)?)?)",
                            @"([235679][.][0-2]([.][2])?)" //standalone 2.0, 2.1, 3.1, 5.1, 5.2, 6.1, 6.2, 7.1, 7.1.2, 9.1, 9.1.2
                        };
                        string channel = string.Join("|", channelList);
        
                        // Bit Depth
                        string bitDepth = @"(\d+[\-\s]?bit)";
        
                        // Tags
                        string tags = @"(\[.*?\])"; // [tag] // do not wrap with \b
        
                        // Formats
                        IEnumerable<string> formatsList = new List<string>()
                        {
                            @"(DVD|BRD|BD|Br|HD|SD|Web)[\-\s]?(Rip|DL)?",
                            @"(HD|SD)(TV|R|C)?",
                            @"Blu[\-\s]?Ray",
                            @"Rip",
                            @"(\d+)?CD",
                            @"Playlist",
                        };
                        string formats = "(" + string.Join("|", formatsList) + ")";
        
                        // Containers
                        IEnumerable<string> containersList = Generate.Format.VideoFormats
                                                             .Concat(Generate.Format.AudioFormats)
                                                             .Concat(Generate.Format.ImageFormats)
                                                             .Distinct()
                                                             .OrderByDescending(x => x)
                                                             .ToList();
        
                        // Remove Formats that are also Codecs
                        // These are usually for raw files
                        // This will prevent regex from running into duplicates in other categories
                        containersList = containersList.Except(Types.Codecs.CodecTypes, StringComparer.OrdinalIgnoreCase).ToList();
                        string containers = "(" + string.Join("|", containersList) + ")";
        
                        // Codecs
                        List<string> codecsList = new List<string>()
                        {
                            "RAW",
                            "Lossless",
                            "HEVC",
                            @"(H[.\-]?)?(x)?26(4|5)[.\-\s]?(QOQ)?", // H.264, x264, x264-QOQ
                            "QOQ",
                            "NF",
                            "FP",
                        };
                        codecsList.AddRange(Types.Codecs.CodecTypes);
                        string codecs = "(" + string.Join("|", codecsList) + ")";
        
                        // Video
                        IEnumerable<string> videoList = new List<string>()
                        {
                            "((UH|H|S)D)", // UHD, HD, SD
                            @"\d+[\-\s]?bit",
                        };
                        string video = "(" + string.Join("|", videoList) + ")";
        
                        // Audio
                        IEnumerable<string> audioList = new List<string>()
                        {
                            @"(Dual|Multi|Original|Orig|Org)[\-\s]?(Audio|Aud)",
                            langs + @"[\-\s]?Dub",
                            @"(Non[\-\s])?English[\-\s]?Translated",
                            @"Dub(bed)?",
                        };
                        string audio = "(" + string.Join("|", audioList) + ")";
        
                        // File
                        string file = @"(\d+([.]?\d+?)?[.\-_\s]?((M|G|T)B))"; //100.5MB, 100GB, 100TB
        
                        // Labels
                        IEnumerable<string> labelsList = new List<string>()
                        {
                            "Amazon",
                            "AMZN",
                            "iTunes",
                            "Spotify",
                            "Repack",
                            "Complete",
                        };
                        string labels = "(" + string.Join("|", labelsList) + ")";
        
                        // Custom
                        string custom = string.Empty;
                        if (!string.IsNullOrWhiteSpace(VM.ConfigureView.InputFileNameTokensCustom_Text))
                        {
                            string[] arrInputFileNameTokensCustom_Items = VM.ConfigureView.InputFileNameTokensCustom_Text
                                                                          .Split(',');
        
                            List<string> listInputFileNameTokensCustom_Items = new List<string>(); // Regex Escaped
                            for (var i = 0; i < arrInputFileNameTokensCustom_Items.Length; i++)
                            {
                                // Add item to list
                                // Replace invalid filename characters
                                // Escape for Regex rules
                                listInputFileNameTokensCustom_Items.Add(Regex.Escape(Regex.Replace(arrInputFileNameTokensCustom_Items[i].Trim(), "[\\/:*?\"<>|]", "")));
                            }
        
                            listInputFileNameTokensCustom_Items = listInputFileNameTokensCustom_Items // Clean up and remove empty strings from list
                                                                  .Where(s => !string.IsNullOrWhiteSpace(s))
                                                                  .Distinct()
                                                                  .ToList();
        
                            custom = "(" + string.Join("|", listInputFileNameTokensCustom_Items) + ")";
                        }
        
                        //MessageBox.Show(custom); //debug
        
                        // Symbols
                        // Stray Parentheses
                        string symbols = @"\(\)|\(\s+\)"; // do not wrap with \b
        
        
                        // Build regex rules
                        // Order is important
                        IEnumerable<string> regexTagsList = new List<string>()
                        {
                            tags,
                            @"((?<=_)|\b)(", // opening
                            hwAccelTranscode,
                            sampleRate,
                            bitRate,
                            channel,
                            pixelFormat,
                            formats,
                            containers,
                            codecs,
                            @"(cv-copy)",
                            @"(ca-copy)",
                            video,
                            pass,
                            presets,
                            profile,
                            size,
                            @"(sz-source)",
                            scaling,
                            fps,
                            subtitles,
                            audio,
                            bitDepth,
                            file,
                            labels,
                            custom,
                            @")((?=_)|\b)", //closing
                            symbols,
                        };
        
                        string regexTags = string.Join("|", regexTagsList
                                                     // don't re-order
                                                     .Distinct()
                                               )
                                               // Remove invalid rules caused by adding "((?<=_)|\b)(" to the list
                                               .Replace("(|", "(")
                                               .Replace("|)", ")");
        
                        // Remove Tags and Tokens
                        filename = Regex.Replace(
                            filename,
                            regexTags,
                            "",
                            RegexOptions.IgnoreCase
                        );
        
                        // Fix Multiple Spaces, Periods, Dashes, Underscores
                        filename = Regex.Replace(filename, @"[ ]{1,}", " ");
                        filename = Regex.Replace(filename, @"[.]{1,}", ".");
                        filename = Regex.Replace(filename, @"[\-]{1,}", "-");
                        filename = Regex.Replace(filename, @"[_]{1,}", "_");
        
                        //MessageBox.Show(filename); //debug
        
                        //// Log Console Message /////////
                        //Log.WriteAction = () =>
                        //{
                        //    Log.logParagraph.Inlines.Add(new LineBreak());
                        //    Log.logParagraph.Inlines.Add(new Bold(new Run("Tag Remover Regex:\r\n")) { Foreground = Log.ConsoleDefault });
                        //    Log.logParagraph.Inlines.Add(new Run(regexTags) { Foreground = Log.ConsoleDefault });
                        //};
                        //Log.LogActions.Add(Log.WriteAction);
        
                        return filename
                               .Trim()
                               .Trim('.')
                               .Trim('-')
                               .Trim('_');
                    }
        
                    // stay the same
                    else
                    {
                        return filename;
                    }
                }

        // >>> member: SettingsCheck
                public static String SettingsCheck(string s)
                {
                    // Fail
                    if (string.IsNullOrWhiteSpace(s) ||
                        s.Equals("off", StringComparison.OrdinalIgnoreCase) ||
                        s.Equals("none", StringComparison.OrdinalIgnoreCase) ||
                        s.Equals("auto", StringComparison.OrdinalIgnoreCase) ||
                        s.Equals("CRF", StringComparison.OrdinalIgnoreCase) || // Use CRF TextBox instead of Pass
                        s.Equals("Custom", StringComparison.OrdinalIgnoreCase)
                        )
                    {
                        return string.Empty;
                    }
                    // Pass
                    else
                    {
                        return s;
                    }
                }

        // >>> member: ThreadDetect
                public static String ThreadDetect()
                {
                    // Default / Off
                    if (VM.ConfigureView.Threads_SelectedItem == "Default")
                    {
                        // Optimal
                        Controls.Configure.threads = "";
        
                        return Controls.Configure.threads;
                    }
        
                    // Fallback if maxthreads was not detected in SystemInfo()
                    if (string.IsNullOrWhiteSpace(Controls.Configure.threads))
                    {
                        // Optimal
                        Controls.Configure.threads = "-threads 0";
        
                        return Controls.Configure.threads;
                    }
        
                    // Options
                    switch (VM.ConfigureView.Threads_SelectedItem)
                    {
                        // Empty
                        case "":
                            Controls.Configure.threads = string.Empty;
                            break;
        
                        // Default / Off
                        //case "Default":
                        //    Configure.threads = string.Empty;
                        //    break;
        
                        // Optimal
                        case "Optimal":
                            Controls.Configure.threads = "-threads 0";
                            break;
        
                        // All
                        case "All":
                            // e.g. -threads 8
                            Controls.Configure.threads = "-threads " + Controls.Configure.maxthreads;
                            break;
        
                        // Selected Number
                        default:
                            // e.g. -threads 5
                            Controls.Configure.threads = "-threads " + VM.ConfigureView.Threads_SelectedItem;
                            break;
                    }
        
                    return Controls.Configure.threads;
                }

        // >>> member: Sort
                public static void Sort()
                {
                    // Only if Script not empty
                    if (!string.IsNullOrWhiteSpace(scriptText/*VM.MainView.ScriptView_Text*/))
                    {
                        // -------------------------
                        // Has Not Been Edited
                        // -------------------------
                        if (Controls.ScriptView.sort == false &&
                            RemoveLineBreaks(scriptText/*VM.MainView.ScriptView_Text*/) == Generate.FFmpeg.ffmpegArgs)
                        {
                            VM.MainView.ScriptView_Text = Generate.FFmpeg.ffmpegArgsSort;
        
                            // Sort is Off
                            Controls.ScriptView.sort = true;
                            // Change Button Back to Inline
                            VM.MainView.Sort_Text = "Inline";
                        }
        
                        // -------------------------
                        // Has Been Edited
                        // -------------------------
                        else if (Controls.ScriptView.sort == false &&
                                 RemoveLineBreaks(scriptText/*VM.MainView.ScriptView_Text*/) != Generate.FFmpeg.ffmpegArgs)
                        {
                            MessageBox.Show("Cannot sort custom or edited text.",
                                            "Notice",
                                            MessageBoxButton.OK,
                                            MessageBoxImage.Exclamation);
        
                            return;
                        }
        
        
                        // -------------------------
                        // Inline
                        // -------------------------
                        else if (Controls.ScriptView.sort == true)
                        {
                            // CMD Arguments are from Script TextBox
                            Generate.FFmpeg.ffmpegArgs = RemoveLineBreaks(scriptText/*VM.MainView.ScriptView_Text*/);
        
                            VM.MainView.ScriptView_Text = Generate.FFmpeg.ffmpegArgs;
        
                            // Sort is On
                            Controls.ScriptView.sort = false;
                            // Change Button Back to Sort
                            VM.MainView.Sort_Text = "Sort";
                        }
                    }
                }

        // >>> member: YouTubeDownloadFormat
                public static String YouTubeDownloadFormat(string youtubedl_SelectedItem,
                                                           string videoCodec_SelectedItem,
                                                           string subtitleCodec_SelectedItem,
                                                           string audioCodec_SelectedItem
                                                           )
                {
                    // Video + Audio
                    if (youtubedl_SelectedItem == "Video + Audio")
                    {
                        // Use mp4 for Download-Only Mode
                        if (IsWebDownloadOnly(videoCodec_SelectedItem,
                                              subtitleCodec_SelectedItem,
                                              audioCodec_SelectedItem) == true
                                              )
                        {
                            return "mp4";
                        }
        
                        // Use mkv for converting
                        else
                        {
                            return "mkv";
                        }
                    }
        
                    // Video Only
                    else if (youtubedl_SelectedItem == "Video Only")
                    {
                        // Use mp4 for Download-Only Mode
                        if (IsWebDownloadOnly(videoCodec_SelectedItem,
                                              subtitleCodec_SelectedItem,
                                              audioCodec_SelectedItem) == true
                                              )
                        {
                            return "mp4";
                        }
        
                        // Use mkv for converting
                        else
                        {
                            return "mkv";
                        }
                    }
        
                    // Audio Only
                    else if (youtubedl_SelectedItem == "Audio Only")
                    {
                        // Can only use m4a, not mp3
        
                        return "m4a";
                    }
        
                    return string.Empty;
                }

        // >>> member: YouTubeDownloadQuality
                public static String YouTubeDownloadQuality(string input_Text,
                                                            string youtubedl_SelectedItem,
                                                            string youtubedl_Quality_SelectedItem
                                                            )
                {
                    // -------------------------
                    // Video + Audio
                    // -------------------------
                    if (youtubedl_SelectedItem == "Video + Audio")
                    {
                        switch (youtubedl_Quality_SelectedItem)
                        {
                            // Best
                            case "best":
                                return "bestvideo[ext=mp4]+bestaudio[ext=m4a]/bestvideo+bestaudio/best";
        
                            // Best 4K
                            case "best 4K":
                                return "bestvideo[height=2160][ext=mp4]+bestaudio[ext=m4a]/bestvideo[height=2160]+bestaudio/bestvideo[ext=mp4]+bestaudio[ext=m4a]/bestvideo+bestaudio/best";
        
                            // Best 1080p
                            case "best 1080p":
                                return "bestvideo[height=1080][ext=mp4]+bestaudio[ext=m4a]/bestvideo[height=1080]+bestaudio/bestvideo[ext=mp4]+bestaudio[ext=m4a]/bestvideo+bestaudio/best";
        
                            // Best 720p
                            case "best 720p":
                                return "bestvideo[height=720][ext=mp4]+bestaudio[ext=m4a]/bestvideo[height=720]+bestaudio/bestvideo[ext=mp4]+bestaudio[ext=m4a]/bestvideo+bestaudio/best";
        
                            // Best 480p
                            case "best 480p":
                                return "bestvideo[height=480][ext=mp4]+bestaudio[ext=m4a]/bestvideo[height=480]+bestaudio/bestvideo[ext=mp4]+bestaudio[ext=m4a]/bestvideo+bestaudio/best";
        
                            // Worst
                            case "worst":
                                return "worstvideo[ext=mp4]+worstaudio[ext=m4a]/worstvideo+worstaudio/worst";
                        }
                    }
        
                    // -------------------------
                    // Video Only
                    // -------------------------
                    else if (youtubedl_SelectedItem == "Video Only")
                    {
                        switch (youtubedl_Quality_SelectedItem)
                        {
                            // Best
                            case "best":
                                return "bestvideo[ext=mp4]/bestvideo";
        
                            // Best 4K
                            case "best 4K":
                                return "bestvideo[height=2160][ext=mp4]/bestvideo[ext=mp4]/bestvideo";
        
                            // Best 1080p
                            case "best 1080p":
                                return "bestvideo[height=1080][ext=mp4]/bestvideo[ext=mp4]/bestvideo";
        
                            // Best 720p
                            case "best 720p":
                                return "bestvideo[height=720p][ext=mp4]/bestvideo[ext=mp4]/bestvideo";
        
                            // Best 480p
                            case "best 480p":
                                return "bestvideo[height=480p][ext=mp4]/bestvideo[ext=mp4]/bestvideo";
        
                            // Worst
                            case "worst":
                                return "worstvideo[ext=mp4]/worstvideo";
        
                        }
                    }
        
                    // -------------------------
                    // Audio Only
                    // -------------------------
                    else if (youtubedl_SelectedItem == "Audio Only")
                    {
                        // Best
                        if (youtubedl_Quality_SelectedItem == "best")
                        {
                            return "bestaudio[ext=m4a]/bestaudio";
                        }
                        // Worst
                        else if (youtubedl_Quality_SelectedItem == "worst")
                        {
                            return "worstaudio[ext=m4a]/worstaudio";
                        }
                    }
        
        
                    return string.Empty;
                }

        // >>> member: YouTubeDownloadURL
                public static String YouTubeDownloadURL(string url)
                {
                    // Strip URL Parameters
                    int index = url.IndexOf("&");
                    if (index > 0)
                        url = url.Substring(0, index);
        
                    return url;
                }

        // >>> member: OutputFileNameSpacing
                public static String OutputFileNameSpacing(string filename)
                {
                    switch (VM.ConfigureView.OutputFileNameSpacing_SelectedItem)
                    {
                        case "Original":
                            return filename;
        
                        case "Spaces":
                            // periods
                            filename = Regex.Replace(filename, @"(?<!CRF\d*)(\d[.]\d)|[.]", m => m.Groups[1].Success ? m.Groups[1].Value : " ");
                            // dashes
                            filename = Regex.Replace(filename, @"(-+)|-", "$1");
                            // underscores
                            filename = Regex.Replace(filename, "_", " ");
                            return filename;
        
                        case "Periods":
                            // spaces
                            filename = Regex.Replace(filename, " ", ".");
                            // dashes
                            filename = Regex.Replace(filename, "-", ".");
                            // underscores
                            filename = Regex.Replace(filename, "_", ".");
                            return filename;
        
                        case "Dashes":
                            // spaces
                            filename = Regex.Replace(filename, " ", "-");
                            // periods
                            filename = Regex.Replace(filename, @"(?<!CRF\d*)(\d[.]\d)|[.]", m => m.Groups[1].Success ? m.Groups[1].Value : "-");
                            // underscores
                            filename = Regex.Replace(filename, "_", "-");
                            return filename;
        
                        case "Underscores":
                            // spaces
                            filename = Regex.Replace(filename, " ", "_");
                            // periods
                            filename = Regex.Replace(filename, @"(?<!CRF\d*)(\d[.]\d)|[.]", m => m.Groups[1].Success ? m.Groups[1].Value : "_");
                            // dashes
                            filename = Regex.Replace(filename, "-", "_");
                            return filename;
        
                        default:
                            return filename;
                    }
                }

