                public static bool SavePreviousItemCond(string selectedItem)
                {
                    // Halt
                    if (string.IsNullOrWhiteSpace(selectedItem))
                    {
                        return false;
                    }
        
                    // Halt
                    if (selectedItem.ToLower() == "default" &&
                        selectedItem.ToLower() == "auto" &&
                        selectedItem.ToLower() == "none")
                    {
                        return false;
                    }
                    // Pass
                    else
                    {
                        return true;
                    }
                }

