                            VM.AudioView.Audio_Quality_SelectedItem = "None";
        
                            // Compression Level
                            VM.AudioView.Audio_CompressionLevel_SelectedItem = "none";
        
                            // Sample Rate
                            VM.AudioView.Audio_SampleRate_SelectedItem = "auto";
        
